action.mutation:
mutation CreateInventoryTransaction($payload: [InventoryTransactionCreatePayloadInput!]!) {
  mutation: createInventoryTransaction(payload: $payload) { 
    id
    number
  }
}

mutation UpdateInventoryTransaction($payload: [InventoryTransactionUpdatePayloadInput!]!) {
  mutation: updateInventoryTransaction(payload: $payload) { 
    id
    number
  }
}

mutation DeleteInventoryTransaction($payload: [InventoryTransactionDeletePayloadInput!]!) {
  mutation: deleteInventoryTransaction(payload: $payload) { 
    id
    number
  }
}
